    # edge of the 4-shape.
    r0, r1 = min(r for r, c in obj), max(r for r, c in obj)
    c0, c1 = min(c for r, c in obj), max(c for r, c in obj)
    mr = sum(r for r, c in markers) / len(markers)
    mc = sum(c for r, c in markers) / len(markers)
    orow, ocol = sum(r for r, c in obj) / len(obj), sum(c for r, c in obj) / len(obj)

    if abs(mr - orow) >= abs(mc - ocol):
        if mr > orow:
            axis2 = 2 * r1 + 1
        else:
            axis2 = 2 * r0 - 1
        for r, c in obj:
            rr = axis2 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        if mc > ocol:
            axis2 = 2 * c1 + 1
        else:
            axis2 = 2 * c0 - 1
        for r, c in obj:
            cc = axis2 - c
            if 0 <= cc < w:
                out[r][cc] = 4

    return out
